(async function submit(choice,received){
const records=load("mcts_bench_records"),cases=load("mcts_bench_cases");
async function search(c){
const started=Date.now();let result,error=null;
try{result=await tools.mcp__harness_router__route_mcts(c.input);}catch(e){error=String(e);}
const ended=Date.now();let decision=result?.structuredContent??null;
if(!decision&&result?.content){for(const block of result.content){if(block.type==="text"){try{decision=JSON.parse(block.text);break;}catch{}}}}
return {started_at_ms:started,ended_at_ms:ended,elapsed_ms:ended-started,decision,error,raw:result??null};
}
const active=load("mcts_bench_active");
if(active){
if(typeof choice!=="string"||!active.case.native_input.choices.some(c=>c.name===choice)) throw Error("Invalid choice");
const native={started_at_ms:active.started,ended_at_ms:received,elapsed_ms:received-active.started,tool:choice};
store("mcts_bench_active",null);
const mcts=active.mcts??await search(active.case);
records.push({...active.case,native,mcts});store("mcts_bench_records",records);store("mcts_bench_index",records.length);
if(records.length%4===0){text({block_complete:records.length,total:cases.length,mcts_fallbacks:records.filter(r=>r.mcts.decision?.fallback).length,errors:records.filter(r=>r.mcts.error||r.mcts.raw?.isError).length});return;}
}else if(choice!==null){throw Error("No active trial");}
const index=load("mcts_bench_index");
if(index>=cases.length){text({complete:true,trials:records.length});return;}
const c=cases[index];const mcts=c.order==="mcts_first"?await search(c):null;
const started=Date.now();store("mcts_bench_active",{case:c,mcts,started});
text({trial:c.trial,total:cases.length,instruction:"Select one root action using the stated reward objective. Record its name only; do not execute it or use another tool to compute the choice.",...c.native_input});
})
